/**  How a place is written on a print (FR-005). */
export type PlaceFormat = 
/**  `Debrecen` */
"city" | 
/**  `Debrecen, HU` */
"cityCountryCode" | 
/**  `Debrecen, Hungary` */
"cityCountry";

/**  A physical print size. Dimensions are stored short edge first, in millimetres. */
export type PrintSize = {
	/**  Stable identifier used in settings and IPC, e.g. `"10x15"`. */
	id: string,
	shortMm: number,
	longMm: number,
};

/**  Why the best photo won, compared with the runner-up. The UI words these (FR-020). */
export type Reason = 
/**
 *  Sharper: edges this many percent stronger than the runner-up's (gradient magnitude,
 *  the square root of the Tenengrad energy). A percentage reads better than a sigma, and
 *  small groups have no meaningful sigma.
 */
{ kind: "sharper"; percent: number | null } | 
/**  Less camera shake. */
{ kind: "steadierShot" } | 
/**  Everyone's eyes are open (and not in the runner-up). */
{ kind: "eyesOpen" } | 
/**  Closer to a good exposure. */
{ kind: "betterExposure" } | 
/**  Fewer blown highlights, as shares of the image. */
{ kind: "fewerHighlights"; best: number | null; runnerUp: number | null } | { kind: "lessNoise" };

export type RejectedSummary = {
	fileName: string,
	code: string,
};

export type RenderSettings = {
	/**  A built-in `PrintSize.id` (e.g. `"10x15"`) or a `CustomPrintSize.id` (FR-006, FR-043). */
	printSize: string,
	stamp: StampSettings,
	/**  User-defined sizes such as 4 × 6 in (FR-043). */
	customSizes?: CustomPrintSize[],
	/**  How place names are written, in the stamp and in the info frame (FR-005). */
	placeFormat?: PlaceFormat,
};

/**  Render-affecting state changed (settings, frame, crops, undo); previews refresh. */
export type RevisionChanged = {
	revision: number,
	canUndo: boolean,
	canRedo: boolean,
};

export type SettingsState = {
	settings: RenderSettings,
	/**  Bumps on every change; previews use it to refresh. */
	revision: number,
};

export type StampColor = "white" | "retroOrange";

export type StampSettings = {
	enabled: boolean,
	format: DateFormat,
	corner: Corner,
	color: StampColor,
	/**
	 *  The place on the same line as the date (FR-005). The stamp is always set in the
	 *  bundled LCD font; user fonts are for the info frame only (FR-042). Settings v4 and
	 *  older had a `font` here, which is ignored.
	 */
	place?: boolean,
	/**
	 *  A line of the user's own text under the date (FR-036), shown in plain upper-case
	 *  letters; empty for none.
	 */
	caption?: string,
};

export type TaskKind = 
/**  Reading files and EXIF during import. */
"import" | 
/**  Generating sharp (T1) thumbnails in the background. */
"thumbnails" | 
/**  Best-shot analysis of the library (FR-041). */
"analyze";

/**  Progress of a background task, for the progress bar (coalesced to ≤ 30 per second). */
export type TaskProgress = {
	task: TaskKind,
	done: number,
	total: number,
};

/**  A sharper thumbnail (T1) is now cached for this photo. */
export type ThumbReady = {
	id: PhotoId,
};

/**  Per-machine interface preferences (FR-020). Never part of a project file. */
export type UiSettings = {
	language: Language,
};

/**
 *  A row of the `fonts` table in `settings.json` (DATABASE.md §6). The file lives at
 *  `config/fonts/<id>.<ttf|otf>`.
 */
export type UserFont = {
	id: number,
	/**  Display name (defaults to the file name). */
	name: string,
	format: FontFormat,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

